//! Scout Desktop's client for Explore chat.
//!
//! - [`contract`]: the route table, refusal statuses and stream event names,
//!   generated by `build.rs` from `desktop-api.contract.json`.
//! - [`model`]: strict serde types for messages, traces, results, cards and
//!   stream events.
//! - [`ExploreClient`]: one typed method per Explore route, authenticated with
//!   the paired device's bearer token and the contract header.
//! - [`stream`]: following a run over SSE, reconnecting until `done`.
//! - [`reducer`]: the web's turn reducer, folding stream events into what a
//!   turn renders.
//! - [`session`]: one desktop chat session as pure state, projected onto the
//!   window's IPC chat parts.
//! - [`relay`]: the supervisor's task that runs the client against a session
//!   and publishes those parts, so the credential never leaves the supervisor.
//!
//! The crate has no UI dependency; the window renders the parts it publishes.

mod client;
pub mod contract;
mod error;
#[cfg(feature = "golden")]
pub mod golden;
pub mod model;
pub mod reducer;
pub mod relay;
pub mod session;
pub mod stream;

pub use client::{ExploreClient, STREAM_IDLE_TIMEOUT};
pub use error::{ExploreClientError, Recovery, Refusal};
